//! Opt-in proof that portal-enrolled synthetic keys can play through the public
//! lobby and its real allocated worker. The fixture contains private seeds and
//! must be generated by the isolated portal registration rehearsal, never prod.
//! Build the server first, then set OMOBA_REGISTRATION_JOURNEY_FIXTURE and an
//! explicit loopback OMOBA_HARNESS_DATABASE_URL ending in /omoba_test.
use ed25519_dalek::{Signer, SigningKey};
use serde::Deserialize;
use shared::{
    career::{AuthChallenge, CareerAction, CareerRequest, CareerView, authorized_signing_bytes},
    map::Team,
    match_service::{MatchAllocation, MatchPreference, MatchServiceView},
    prematch::{PrematchAction, PrematchPhase, PrematchRequest},
    protocol::SnapshotMeta,
    public_transport::{
        PROBE_PADDING_BYTES, PublicClientDatagram, PublicServerDatagram, SignedCommand, decode_hex,
        hex,
    },
    transport::SnapshotAssembler,
    wire::{CharacterChoice, ClientPacket, GameState, PlayerState, ServerPacket},
};
use std::{
    fs::{self, OpenOptions},
    io::{Read, Seek, SeekFrom},
    net::{SocketAddr, UdpSocket},
    path::{Path, PathBuf},
    process::{Child, Command, Stdio},
    thread,
    time::{Duration, Instant, SystemTime, UNIX_EPOCH},
};

const WAIT: Duration = Duration::from_secs(30);
const METHODS: [&str; 3] = ["vkid", "ok_ru", "mail_ru"];
const SEARCH_RETRY: Duration = Duration::from_secs(1);

struct MatchSearch {
    action: CareerAction,
    next_send: Instant,
}
impl MatchSearch {
    fn due(&mut self, now: Instant) -> Option<CareerAction> {
        if now < self.next_send {
            return None;
        }
        self.next_send = now + SEARCH_RETRY;
        Some(self.action.clone())
    }
}

fn signed_account_request(
    key: &SigningKey,
    epoch: u64,
    nonce: &str,
    sequence: u64,
    action: CareerAction,
) -> CareerRequest {
    let signature = hex(&key
        .sign(&authorized_signing_bytes(epoch, nonce, sequence, &action))
        .to_bytes());
    CareerRequest::Authorized {
        session_nonce: nonce.into(),
        sequence,
        action,
        signature,
    }
}

/// Workers report their durable-start wait in the legacy error field, without
/// a typed error code (`ServerRuntime::career_view`). Accept only that exact
/// status for the profile/nonce this peer already authenticated; all real auth,
/// allocation and storage errors still fail the rehearsal immediately.
fn career_reply_rejected(
    view: &CareerView,
    authenticated_nonce: Option<&str>,
    expected_profile: &str,
) -> bool {
    if view.error_code.is_some()
        || matches!(view.match_service, Some(MatchServiceView::Failed { .. }))
    {
        return true;
    }
    match view.error.as_deref() {
        None => false,
        Some("Preparing durable match allocation…") => {
            !(authenticated_nonce.is_some()
                && view.auth_nonce.as_deref() == authenticated_nonce
                && view
                    .profile
                    .as_ref()
                    .is_some_and(|profile| profile.profile_id == expected_profile)
                && !matches!(view.match_service, Some(MatchServiceView::Failed { .. })))
        }
        Some(_) => true,
    }
}

// No Debug: the fixture is an in-process signing capability, never evidence.
#[derive(Deserialize)]
struct Account {
    method: String,
    profile_id: String,
    seed: String,
}

fn isolated_database_url(raw: &str) -> bool {
    let Some(rest) = raw
        .strip_prefix("postgres://")
        .or_else(|| raw.strip_prefix("postgresql://"))
    else {
        return false;
    };
    let Some((authority, database)) = rest.split_once('/') else {
        return false;
    };
    let endpoint = authority.rsplit('@').next().unwrap_or_default();
    let host = endpoint
        .strip_prefix('[')
        .and_then(|s| s.split_once(']'))
        .map(|(host, _)| host)
        .unwrap_or_else(|| endpoint.split(':').next().unwrap_or_default());
    database == "omoba_test" && matches!(host, "127.0.0.1" | "localhost" | "::1")
}

fn accounts() -> Vec<Account> {
    let path = std::env::var_os("OMOBA_REGISTRATION_JOURNEY_FIXTURE")
        .or_else(|| std::env::var_os("OMOBA_NATIVE_JOURNEY_FIXTURE"))
        .map(PathBuf::from)
        .expect("set the task-owned private registration fixture path");
    assert!(path.is_absolute(), "fixture path must be absolute");
    let metadata = fs::symlink_metadata(&path).expect("private fixture metadata");
    assert!(metadata.is_file() && metadata.len() <= 65_536);
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        assert_eq!(
            metadata.permissions().mode() & 0o077,
            0,
            "private fixture permissions"
        );
    }
    let bytes = fs::read(path).expect("read the private fixture");
    let values: Vec<Account> = serde_json::from_slice(&bytes)
        .unwrap_or_else(|_| panic!("invalid private registration fixture JSON"));
    assert!(values.len() <= 16, "bounded fixture account count");
    let selected: Vec<_> = values
        .into_iter()
        .filter(|account| {
            METHODS.contains(&account.method.as_str()) || account.method == "game-first"
        })
        .collect();
    for method in METHODS {
        assert_eq!(
            selected.iter().filter(|a| a.method == method).count(),
            1,
            "one enrolled key per provider method"
        );
    }
    assert!(
        selected.iter().filter(|a| a.method == "game-first").count() <= 1,
        "at most one optional game-initiated account"
    );
    assert!(
        selected.iter().all(|a| {
            shared::career::valid_profile_id(&a.profile_id) && decode_hex::<32>(&a.seed).is_some()
        }),
        "valid synthetic account fixture"
    );
    for (index, account) in selected.iter().enumerate() {
        assert!(
            selected[..index]
                .iter()
                .all(|old| old.profile_id != account.profile_id),
            "provider methods have independent profiles"
        );
    }
    selected
}

/// Own a private process group because the lobby deliberately leaves workers
/// alive on ordinary shutdown. Only this test's lobby and descendants are killed.
struct OwnedLobby {
    child: Child,
    addr: SocketAddr,
    root: PathBuf,
    stopped: bool,
}
impl OwnedLobby {
    fn start(database: &str, capacity: usize) -> Self {
        let binary = std::env::var_os("HARNESS_SERVER_BIN")
            .map(PathBuf::from)
            .or_else(|| harness::server::prebuilt("server"))
            .expect("build the current server before the registration journey");
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root =
            std::env::temp_dir().join(format!("omoba-registration-{}-{stamp}", std::process::id()));
        fs::create_dir(&root).expect("create this test's private root");
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&root, fs::Permissions::from_mode(0o700)).unwrap();
        }
        let addr = UdpSocket::bind("127.0.0.1:0")
            .unwrap()
            .local_addr()
            .unwrap();
        // Reserve a contiguous block while selecting it. The pool still detects
        // any later port race as a bounded allocation failure, never another host.
        let first_port = worker_ports(capacity as u16);
        let mut options = OpenOptions::new();
        options.write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt;
            options.mode(0o600);
        }
        let output = options.open(root.join("server.log")).unwrap();
        let mut command = Command::new(binary);
        command
            .current_dir(&root)
            .env("SERVER_ADDR", addr.to_string())
            .env("OMOBA_SERVER_ROLE", "lobby")
            .env("OMOBA_DATABASE_URL", database)
            .env("OMOBA_MATCH_MODE", "release")
            .env("OMOBA_MATCH_ROOT", root.join("matches"))
            .env("OMOBA_CAREER_OUTBOX", root.join("outbox"))
            .env("OMOBA_MATCH_CAPACITY", capacity.to_string())
            .env("OMOBA_MATCH_FIRST_PORT", first_port.to_string())
            .env("OMOBA_MATCH_BIND_IP", "127.0.0.1")
            .env("OMOBA_MATCH_PUBLIC_HOST", "127.0.0.1")
            // Four independent fixture users share one loopback source. Only
            // this owned rehearsal raises the production per-source budgets.
            .env("OMOBA_LIMIT_ARENAS_PER_IP", capacity.to_string())
            .env("OMOBA_LIMIT_ENDPOINTS_PER_IP", "16")
            .env_remove("OMOBA_MAP_CONFIG")
            .env_remove("OMOBA_MATCH_ALLOCATION")
            .env_remove("OMOBA_MATCH_RECOVERY")
            .env_remove("OMOBA_MATCH_EXECUTABLE")
            .stdout(Stdio::from(output.try_clone().unwrap()))
            .stderr(Stdio::from(output));
        #[cfg(unix)]
        {
            use std::os::unix::process::CommandExt;
            command.process_group(0);
        }
        let child = command.spawn().expect("launch the prebuilt loopback lobby");
        Self {
            child,
            addr,
            root,
            stopped: false,
        }
    }
    #[cfg(unix)]
    fn group_members(&self) -> Vec<u32> {
        let output = Command::new("ps")
            .args(["-axo", "pid=,pgid="])
            .output()
            .expect("inspect the test-owned process group");
        assert!(output.status.success(), "process-group inventory");
        String::from_utf8_lossy(&output.stdout)
            .lines()
            .filter_map(|line| {
                let mut columns = line.split_whitespace();
                let pid: u32 = columns.next()?.parse().ok()?;
                let group: u32 = columns.next()?.parse().ok()?;
                (group == self.child.id()).then_some(pid)
            })
            .collect()
    }
    fn stop(&mut self) -> bool {
        if self.stopped {
            return true;
        }
        #[cfg(unix)]
        {
            let group = format!("-{}", self.child.id());
            for signal in ["-TERM", "-KILL"] {
                if !self.group_members().is_empty() {
                    let _ = Command::new("/bin/kill")
                        .args([signal, "--", &group])
                        .stdout(Stdio::null())
                        .stderr(Stdio::null())
                        .status();
                }
                let deadline = Instant::now() + Duration::from_secs(2);
                loop {
                    let _ = self.child.try_wait();
                    if self.group_members().is_empty() {
                        self.stopped = true;
                        return true;
                    }
                    if Instant::now() >= deadline {
                        break;
                    }
                    thread::sleep(Duration::from_millis(20));
                }
            }
        }
        #[cfg(windows)]
        {
            let _ = Command::new("taskkill")
                .args(["/PID", &self.child.id().to_string(), "/T", "/F"])
                .stdout(Stdio::null())
                .stderr(Stdio::null())
                .status();
        }
        let _ = self.child.kill();
        let _ = self.child.wait();
        #[cfg(unix)]
        {
            self.stopped = self.group_members().is_empty();
        }
        #[cfg(not(unix))]
        {
            self.stopped = true;
        }
        self.stopped
    }
}
impl Drop for OwnedLobby {
    fn drop(&mut self) {
        if !self.stop() {
            eprintln!("test-owned process cleanup did not finish");
        }
        if thread::panicking() {
            eprintln!(
                "registration lobby diagnostics:\n{}",
                log_tail(&self.root.join("server.log"))
            );
            if let Ok(entries) = fs::read_dir(self.root.join("matches")) {
                for entry in entries.flatten().take(4) {
                    let path = entry.path().join("worker.log");
                    if path.is_file() {
                        eprintln!("registration worker diagnostics:\n{}", log_tail(&path));
                    }
                }
            }
        }
        let _ = fs::remove_dir_all(&self.root); // Only this invocation's own root.
    }
}

fn log_tail(path: &Path) -> String {
    let Ok(mut file) = fs::File::open(path) else {
        return "unavailable".into();
    };
    let size = file.metadata().map_or(0, |m| m.len()).min(16_384);
    let _ = file.seek(SeekFrom::End(-(size as i64)));
    let mut bytes = Vec::new();
    let _ = file.take(size).read_to_end(&mut bytes);
    String::from_utf8_lossy(&bytes).into_owned()
}

fn worker_ports(capacity: u16) -> u16 {
    for _ in 0..100 {
        let first = UdpSocket::bind("127.0.0.1:0").unwrap();
        let port = first.local_addr().unwrap().port();
        if port > u16::MAX - capacity {
            continue;
        }
        let mut sockets = vec![first];
        for offset in 1..capacity {
            match UdpSocket::bind(("127.0.0.1", port + offset)) {
                Ok(socket) => sockets.push(socket),
                Err(_) => break,
            }
        }
        if sockets.len() == usize::from(capacity) {
            return port;
        }
    }
    panic!("cannot reserve the task-owned worker ports");
}

struct Peer {
    socket: UdpSocket,
    key: SigningKey,
    expected_profile: String,
    session: String,
    client_nonce: String,
    path: String,
    epoch: u64,
    meta: SnapshotMeta,
    challenge: Option<AuthChallenge>,
    auth_nonce: Option<String>,
    career: CareerView,
    snapshot: Option<ServerPacket>,
    assembler: SnapshotAssembler,
    gameplay_sequence: u64,
    account_sequence: u64,
    search: Option<MatchSearch>,
    prematch_sequence: u64,
    next_send: Instant,
}
impl Peer {
    fn connect(endpoint: SocketAddr, account: &Account, session: &str) -> Self {
        assert!(
            endpoint.ip().is_loopback(),
            "journey endpoints stay on loopback"
        );
        let socket = UdpSocket::bind("127.0.0.1:0").unwrap();
        socket.connect(endpoint).unwrap();
        socket.set_nonblocking(true).unwrap();
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let mut peer = Self {
            socket,
            key: SigningKey::from_bytes(&decode_hex::<32>(&account.seed).expect("synthetic seed")),
            expected_profile: account.profile_id.clone(),
            session: session.into(),
            client_nonce: format!("{stamp:032x}"),
            path: String::new(),
            epoch: 0,
            meta: SnapshotMeta::default(),
            challenge: None,
            auth_nonce: None,
            career: CareerView::default(),
            snapshot: None,
            assembler: SnapshotAssembler::default(),
            gameplay_sequence: 0,
            account_sequence: 0,
            search: None,
            prematch_sequence: 0,
            next_send: Instant::now(),
        };
        peer.wait("signed career admission", |p| {
            p.auth_nonce.is_some() && p.meta.match_id != 0
        });
        assert_eq!(
            peer.career.profile.as_ref().unwrap().profile_id,
            account.profile_id,
            "enrolled key resolves the website's profile"
        );
        peer
    }
    fn send(&self, packet: &PublicClientDatagram) {
        self.socket
            .send(&serde_json::to_vec(packet).unwrap())
            .expect("loopback public datagram");
    }
    fn bootstrap(&self, request: CareerRequest) {
        self.send(&PublicClientDatagram::TransportBootstrap {
            path_nonce: self.path.clone(),
            payload: serde_json::to_string(&ClientPacket::Career { request }).unwrap(),
        });
    }
    fn gameplay(&mut self, packet: ClientPacket) {
        self.gameplay_sequence += 1;
        let mut command = SignedCommand {
            server_epoch: self.epoch,
            match_id: self.meta.match_id,
            session_id: self.session.clone(),
            session_nonce: self.auth_nonce.clone().expect("authenticated gameplay"),
            path_nonce: self.path.clone(),
            sequence: self.gameplay_sequence,
            payload: serde_json::to_string(&packet).unwrap(),
            signature: String::new(),
        };
        command.signature = hex(&self.key.sign(&command.signing_bytes()).to_bytes());
        self.send(&PublicClientDatagram::SignedCommand { command });
    }
    fn drive(&mut self) {
        let now = Instant::now();
        if now < self.next_send {
            return;
        }
        self.next_send = now + Duration::from_millis(300);
        if self.epoch == 0 {
            self.send(&PublicClientDatagram::TransportProbe {
                protocol_version: shared::protocol::PROTOCOL_VERSION,
                client_nonce: self.client_nonce.clone(),
                padding: "0".repeat(PROBE_PADDING_BYTES),
            });
        } else if self.auth_nonce.is_some() && self.meta.match_id != 0 {
            // The server deliberately drops account requests made within 100ms
            // of the previous one. A fast Authenticate reply can therefore
            // overtake the first FindMatch; UDP can also lose any one request.
            // Keep the search intent, but give each retry a fresh replay sequence.
            if let Some(action) = self.search.as_mut().and_then(|search| search.due(now)) {
                self.account_sequence += 1;
                self.bootstrap(signed_account_request(
                    &self.key,
                    self.epoch,
                    self.auth_nonce.as_deref().unwrap(),
                    self.account_sequence,
                    action,
                ));
            }
            let readiness = match &self.snapshot {
                Some(ServerPacket::Snapshot {
                    your_id,
                    prematch: Some(draft),
                    ..
                }) => draft
                    .players
                    .iter()
                    .find(|player| player.player_id == *your_id)
                    .and_then(|own| match draft.phase {
                        PrematchPhase::Draft if !own.locked => {
                            Some((draft.generation, PrematchAction::Lock { locked: true }))
                        }
                        PrematchPhase::Loading if !own.loaded => {
                            Some((draft.generation, PrematchAction::Loaded))
                        }
                        _ => None,
                    }),
                _ => None,
            };
            if let Some((generation, action)) = readiness {
                self.prematch_sequence += 1;
                self.gameplay(ClientPacket::Prematch {
                    request: PrematchRequest {
                        server_epoch: self.epoch,
                        match_id: self.meta.match_id,
                        generation,
                        request_id: self.prematch_sequence,
                        action,
                    },
                });
            } else {
                self.gameplay(ClientPacket::Ping);
            }
        } else {
            self.send(&PublicClientDatagram::TransportProof {
                server_epoch: self.epoch,
                path_nonce: self.path.clone(),
            });
            if let Some(challenge) = self.challenge.clone() {
                self.bootstrap(CareerRequest::Authenticate {
                    signature: hex(&self.key.sign(&challenge.signing_bytes()).to_bytes()),
                    challenge,
                });
            } else {
                self.bootstrap(CareerRequest::Challenge {
                    public_key: hex(self.key.verifying_key().as_bytes()),
                    nickname: "Player".into(),
                    session_id: self.session.clone(),
                });
            }
        }
    }
    fn receive(&mut self) {
        let mut bytes = [0_u8; 65_536];
        while let Ok(len) = self.socket.recv(&mut bytes) {
            if let Ok(PublicServerDatagram::TransportChallenge {
                server_epoch,
                client_nonce,
                path_nonce,
                ..
            }) = serde_json::from_slice(&bytes[..len])
            {
                if client_nonce == self.client_nonce && self.epoch == 0 {
                    self.epoch = server_epoch;
                    self.path = path_nonce;
                    self.next_send = Instant::now();
                }
                continue;
            }
            let Some(payload) = self
                .assembler
                .push(&bytes[..len], Instant::now())
                .expect("bounded snapshot frames")
            else {
                continue;
            };
            let packet: ServerPacket =
                serde_json::from_slice(&payload).expect("server wire contract");
            match packet {
                ServerPacket::Career { career, .. } => {
                    assert!(
                        !career_reply_rejected(
                            &career,
                            self.auth_nonce.as_deref(),
                            &self.expected_profile,
                        ),
                        "career admission/action rejected: error={:?}, code={:?}, match_service={:?}",
                        career.error,
                        career.error_code,
                        career.match_service
                    );
                    if let Some(challenge) = career.challenge.as_ref().filter(|c| {
                        c.public_key == hex(self.key.verifying_key().as_bytes())
                            && c.session_id == self.session
                            && c.server_epoch == self.epoch
                    }) {
                        if self.challenge.as_ref() != Some(challenge) {
                            self.challenge = Some(challenge.clone());
                            self.next_send = Instant::now();
                        }
                    }
                    if let Some(challenge) = &self.challenge {
                        if career.auth_nonce.as_ref() == Some(&challenge.nonce)
                            && career.profile.is_some()
                        {
                            self.auth_nonce = Some(challenge.nonce.clone());
                        }
                    }
                    self.career = career;
                }
                packet @ ServerPacket::Snapshot { .. } => {
                    let ServerPacket::Snapshot { meta, .. } = &packet else {
                        unreachable!()
                    };
                    if meta.server_epoch == self.epoch
                        && meta.snapshot_tick > self.meta.snapshot_tick
                    {
                        self.meta = *meta;
                        self.snapshot = Some(packet);
                    }
                }
                _ => {}
            }
        }
    }
    fn wait(&mut self, stage: &str, mut ready: impl FnMut(&Self) -> bool) {
        let deadline = Instant::now() + WAIT;
        while Instant::now() < deadline {
            self.drive();
            self.receive();
            if ready(self) {
                return;
            }
            thread::sleep(Duration::from_millis(5));
        }
        let summary = match &self.snapshot {
            Some(ServerPacket::Snapshot {
                game_state,
                join_error,
                prematch,
                your_id,
                players,
                ..
            }) => {
                format!(
                    "state={game_state:?}, join_error={join_error:?}, own_id={your_id}, visible_actors={}, draft={:?}, own={:?}",
                    players.len(),
                    prematch.as_ref().map(|p| (
                        p.phase,
                        p.generation,
                        p.needed,
                        p.remaining_ms,
                        p.last_request_id,
                        &p.error,
                        p.players
                            .iter()
                            .map(|a| (a.player_id, a.is_bot, a.locked, a.loaded))
                            .collect::<Vec<_>>()
                    )),
                    self.own().map(|a| (a.id, a.x, a.y, a.z, a.yaw, a.hp))
                )
            }
            _ => "no snapshot".into(),
        };
        panic!(
            "registration journey timed out during {stage}; meta={:?}; {summary}; career: profile_matches={}, nonce_matches={}, queue={:?}, match_service={:?}, request_id={:?}, error={:?}, code={:?}, account_sequence={}, gameplay_sequence={}",
            self.meta,
            self.career
                .profile
                .as_ref()
                .is_some_and(|p| p.profile_id == self.expected_profile),
            self.auth_nonce.is_some() && self.career.auth_nonce == self.auth_nonce,
            self.career.queue,
            self.career.match_service,
            self.career.match_service_request_id,
            self.career.error,
            self.career.error_code,
            self.account_sequence,
            self.gameplay_sequence,
        );
    }
    fn find_match(&mut self) -> MatchAllocation {
        let action = CareerAction::FindMatch {
            request_id: 1,
            preference: MatchPreference::BotPractice,
            also_casual: false,
        };
        self.search = Some(MatchSearch {
            action,
            next_send: Instant::now(),
        });
        self.next_send = Instant::now();
        self.wait("public bot-practice allocation", |p| {
            matches!(
                p.career.match_service,
                Some(MatchServiceView::Assigned { .. })
            )
        });
        self.search = None;
        let Some(MatchServiceView::Assigned { allocation, .. }) = self.career.match_service.clone()
        else {
            unreachable!()
        };
        assert_eq!(allocation.preference, MatchPreference::BotPractice);
        allocation
    }
    fn join(&mut self, team: Team) {
        self.gameplay(ClientPacket::Join {
            handheld: Default::default(),
            prematch: true,
            team,
            character: CharacterChoice::Ipfs,
            hero_class: shared::HeroClass::Warrior,
            avatar: None,
            sprite_character: None,
            session_id: Some(self.session.clone()),
            passport_ticket: None,
        });
        self.wait("signed playable join", |p| {
            matches!(
                p.snapshot,
                Some(ServerPacket::Snapshot {
                    game_state: GameState::Running,
                    ..
                })
            ) && p.own().is_some()
        });
        let Some(ServerPacket::Snapshot { join_error, .. }) = &self.snapshot else {
            unreachable!()
        };
        assert!(join_error.is_none(), "signed join accepted");
    }
    fn own(&self) -> Option<&PlayerState> {
        let Some(ServerPacket::Snapshot {
            your_id, players, ..
        }) = &self.snapshot
        else {
            return None;
        };
        players.iter().find(|player| player.id == *your_id)
    }
    fn move_and_observe(&mut self) {
        let before = self.own().unwrap().clone();
        let tick = self.meta.snapshot_tick;
        self.gameplay(ClientPacket::Transform {
            x: before.x + 0.2,
            y: before.y,
            z: before.z,
            yaw: 0.73,
            dash_sequence: before.utility.dash_sequence,
        });
        self.wait("signed movement receipt", |p| {
            p.meta.snapshot_tick > tick
                && p.own()
                    .is_some_and(|own| own.x > before.x + 0.05 && (own.yaw - 0.73).abs() < 0.01)
        });
    }
}

#[test]
fn a_dropped_find_match_retries_the_same_intent_with_a_fresh_signed_sequence() {
    let first_at = Instant::now();
    let action = CareerAction::FindMatch {
        request_id: 7,
        preference: MatchPreference::BotPractice,
        also_casual: false,
    };
    let mut search = MatchSearch {
        action: action.clone(),
        next_send: first_at,
    };
    let key = SigningKey::from_bytes(&[9; 32]);
    let nonce = "b".repeat(64);
    let first = signed_account_request(&key, 11, &nonce, 1, search.due(first_at).unwrap());
    // Ignore the first request, as the server's post-authentication throttle or
    // a lost UDP datagram would. No retry may burst into the 100ms gate.
    assert!(search.due(first_at + Duration::from_millis(100)).is_none());
    let retry = signed_account_request(
        &key,
        11,
        &nonce,
        2,
        search.due(first_at + SEARCH_RETRY).unwrap(),
    );
    let CareerRequest::Authorized {
        sequence: first_sequence,
        action: first_action,
        signature: first_signature,
        ..
    } = first
    else {
        unreachable!()
    };
    let CareerRequest::Authorized {
        sequence,
        action: retry_action,
        signature,
        ..
    } = retry
    else {
        unreachable!()
    };
    assert_eq!(first_action, action);
    assert_eq!(
        retry_action, action,
        "stable request id and queue preference"
    );
    assert_eq!((first_sequence, sequence), (1, 2));
    assert_ne!(
        first_signature, signature,
        "the retry has fresh replay authority"
    );
    let signature = ed25519_dalek::Signature::from_bytes(&decode_hex::<64>(&signature).unwrap());
    key.verifying_key()
        .verify_strict(
            &authorized_signing_bytes(11, &nonce, sequence, &retry_action),
            &signature,
        )
        .unwrap();
    assert!(
        search.due(first_at + SEARCH_RETRY).is_none(),
        "one retry per interval"
    );
}

#[test]
fn authenticated_durable_allocation_wait_is_pending_but_auth_errors_still_fail() {
    let expected = "a".repeat(64);
    let nonce = "b".repeat(64);
    let pending = CareerView {
        profile: Some(shared::career::ProfileSummary::new(
            expected.clone(),
            "Fixture".into(),
        )),
        auth_nonce: Some(nonce.clone()),
        error: Some("Preparing durable match allocation…".into()),
        ..Default::default()
    };
    assert!(!career_reply_rejected(&pending, Some(&nonce), &expected));
    assert!(career_reply_rejected(&pending, None, &expected));
    assert!(career_reply_rejected(
        &pending,
        Some("foreign-nonce"),
        &expected
    ));
    assert!(career_reply_rejected(
        &pending,
        Some(&nonce),
        &"c".repeat(64)
    ));
    for message in [
        "Sign in before using your profile.",
        "Invalid or replayed account request.",
        "Preparing durable match allocation… storage failed",
        "This match is reserved for its allocated roster.",
    ] {
        let view = CareerView {
            error: Some(message.into()),
            match_service: Some(MatchServiceView::Allocating),
            ..pending.clone()
        };
        assert!(career_reply_rejected(&view, Some(&nonce), &expected));
    }
    let banned = CareerView {
        error_code: Some(shared::career::error_code::ACCOUNT_BANNED.into()),
        ..pending.clone()
    };
    assert!(career_reply_rejected(&banned, Some(&nonce), &expected));
    let failed = CareerView {
        match_service: Some(MatchServiceView::Failed {
            code: "storage_unavailable".into(),
        }),
        ..pending
    };
    assert!(career_reply_rejected(&failed, Some(&nonce), &expected));
    let refusal_without_error_text = CareerView {
        error: None,
        ..failed
    };
    assert!(career_reply_rejected(
        &refusal_without_error_text,
        Some(&nonce),
        &expected
    ));
}

#[test]
fn registration_journey_only_accepts_an_explicit_loopback_test_database() {
    assert!(isolated_database_url(
        "postgres://postgres:synthetic@127.0.0.1:56106/omoba_test"
    ));
    assert!(isolated_database_url(
        "postgresql://postgres@localhost:5432/omoba_test"
    ));
    for value in [
        "postgres://postgres@foreign.example/omoba_test",
        "postgres://postgres@127.0.0.1/production",
        "postgres://postgres@127.0.0.1/omoba_test?host=foreign.example",
        "postgres://postgres@127.0.0.1.evil/omoba_test",
    ] {
        assert!(!isolated_database_url(value));
    }
}

#[test]
#[ignore = "requires private portal-enrolled fixture, explicit disposable PostgreSQL and prebuilt server"]
fn registered_provider_accounts_play_and_reconnect_through_the_public_lobby() {
    let database =
        std::env::var("OMOBA_HARNESS_DATABASE_URL").expect("set the isolated harness database URL");
    assert!(
        isolated_database_url(&database),
        "only an explicit loopback omoba_test database is allowed"
    );
    let accounts = accounts();
    let mut lobby = OwnedLobby::start(&database, accounts.len());
    for (index, account) in accounts.iter().enumerate() {
        let session = format!("registration-{}-{index}", account.method);
        let mut home = Peer::connect(lobby.addr, account, &session);
        let allocation = home.find_match();
        #[cfg(unix)]
        assert!(
            lobby.group_members().len() >= 2,
            "allocated worker stays in the test-owned process group"
        );
        let endpoint: SocketAddr = allocation
            .endpoint
            .parse()
            .expect("loopback worker endpoint");
        let mut game = Peer::connect(endpoint, account, &session);
        game.join(allocation.team);
        game.move_and_observe();
        let player = game.own().unwrap().id;
        let match_id = game.meta.match_id;
        if index == 0 {
            drop(game);
            // Public workers detach this seat after the real five-second
            // endpoint timeout. Reauthenticate on a fresh socket and reclaim it.
            thread::sleep(Duration::from_secs(6));
            let mut restored = Peer::connect(endpoint, account, &session);
            restored.join(allocation.team);
            assert_eq!(
                restored.own().unwrap().id,
                player,
                "reconnect keeps the same actor"
            );
            assert_eq!(
                restored.meta.match_id, match_id,
                "reconnect keeps the same match"
            );
            restored.move_and_observe();
        }
        println!(
            "registration journey {}: profile admission, signed public join and movement PASS",
            account.method
        );
    }
    assert!(lobby.stop(), "all owned lobby/worker processes terminated");
    println!("registration journey owned process-group cleanup PASS");
}
